/* doc-clean R13: an email's published copy. The messages are generated by mail-reader's test inputs (bytes this
 * module reads, never another module's answer); the copy is read back by mail-reader's real reader. */
import "../../sandbox.mjs";
import { test } from "node:test";
import assert from "node:assert/strict";
import { cleanDocument } from "../../../src/doc-clean/index.mjs";
import { readMessage, attachmentBytes } from "../../../src/mail-reader/index.mjs";
import { localize } from "../../../src/setup-words/index.mjs";
import * as F from "../mail-reader/fixtures.mjs";
import { pdf, has, SECRETS } from "./fixtures.mjs";

const WITHHELD = localize("doc-clean.mail.withheld", "withheld");
const text = (b) => new TextDecoder("latin1").decode(b);
const HEADERS = [
  "Received: from mx.example.net (mx.example.net [203.0.113.7]) by mail.example.gov; Tue, 6 Oct 2026 09:30:05 -0700",
  "Delivered-To: clerk@example.gov",
  "Return-Path: <ada@example.org>",
  "Authentication-Results: mx.example.gov; spf=pass smtp.mailfrom=example.org; dkim=pass",
  ...F.STANDARD,
];
const copy = async (bytes, opts) => {
  const r = await cleanDocument(bytes, opts);
  assert.equal(r.ok, true);
  assert.equal(r.clean, false);
  return r;
};

test("R13 a message with addresses and Received publishes neither; a marked name appears, an unmarked one is withheld", async () => {
  const msg = F.eml([...HEADERS], "Please send the minutes. Write to ada@example.org about it.");
  const r = await copy(msg, { materialNames: ["Ada Lane"] });
  assert.equal(r.format, "eml");
  const out = text(r.bytes);
  for (const gone of ["Received", "Delivered-To", "Return-Path", "Authentication-Results", "Message-ID", "203.0.113.7", "@", "example.org", "example.gov"])
    assert.equal(out.includes(gone), false, gone);
  const read = await readMessage(r.bytes);
  assert.equal(read.ok, true);
  assert.deepEqual(read.header_fields.map((f) => f.name), ["From", "To", "Cc", "Date", "Subject", "MIME-Version", "Content-Type", "Content-Transfer-Encoding"]);
  assert.equal(read.headers.from, "Ada Lane");
  assert.equal(read.headers.to, WITHHELD);
  assert.equal(read.headers.cc, WITHHELD);
  assert.equal(read.headers.date, "Tue, 6 Oct 2026 09:30:00 -0700");
  assert.equal(read.headers.subject, "Records request");
  assert.equal(read.body.text.includes("Please send the minutes."), true);
});

test("R13 with no material name given every name is withheld", async () => {
  const r = await copy(F.eml([...HEADERS], "Body."));
  const read = await readMessage(r.bytes);
  assert.deepEqual([read.headers.from, read.headers.to, read.headers.cc], [WITHHELD, WITHHELD, WITHHELD]);
});

test("R13 an attached PDF has its metadata removed as R6 states, and the copy answers the same twice", async () => {
  const doc = pdf();
  assert.equal(has(doc, "AUTHORSECRET"), true);
  const msg = F.withAttachments([F.attachmentPart("minutes.pdf", "application/pdf", doc)], "See attached.", HEADERS);
  const r = await copy(msg);
  const read = await readMessage(r.bytes);
  assert.equal(read.attachments.length, 1);
  const cut = await attachmentBytes(r.bytes, 0);
  assert.equal(cut.ok, true);
  for (const s of SECRETS) assert.equal(has(cut.bytes, s), false, s);
  assert.deepEqual(await cleanDocument(msg), r);
});

test("R13 a message whose attachment cannot be cleaned is refused by that attachment's code", async () => {
  const msg = F.withAttachments([F.attachmentPart("macro.bin", "application/octet-stream", new Uint8Array([0, 1, 2, 3]))], "x", HEADERS);
  const r = await cleanDocument(msg);
  assert.equal(r.ok, false);
  assert.equal(r.code, "NOT_A_CLEANABLE_FORMAT");
});

test("R13 a published copy cleaned again is clean: true", async () => {
  const r = await copy(F.eml([...HEADERS], "Body."));
  const again = await cleanDocument(r.bytes);
  assert.deepEqual(again, { ok: true, clean: true, format: "eml" });
});

test("R13 control: a text file that merely contains a From line is not a message and travels whole", async () => {
  const r = await cleanDocument(new TextEncoder().encode("Notes\nFrom: the council office\nend\n"));
  assert.deepEqual(r, { ok: true, clean: true, format: "text" });
});

